INCLUDE PERFETTO MODULE slices.with_context;
WITH r AS (SELECT id,ts,dur FROM thread_slice WHERE id IN (9233,30590,52237)),
overlaps AS (SELECT r.id,MAX(r.ts,s.ts) a,MIN(r.ts+r.dur,s.ts+s.dur) b FROM r JOIN thread_slice s ON s.category IN ('kernel','gpu_memcpy','gpu_memset') AND EXTRACT_ARG(s.arg_set_id,'args.stream')=7 AND s.ts<r.ts+r.dur AND s.ts+s.dur>r.ts),
parts AS (SELECT *,MAX(b) OVER(PARTITION BY id ORDER BY a,b ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING) prev FROM overlaps),
u AS (SELECT id,SUM(MAX(0,b-MAX(a,COALESCE(prev,a)))) busy_ns,MAX(b) last_end FROM parts GROUP BY id)
SELECT r.id,(r.ts-3762433098211544)/1e6 start_ms,r.dur/1e6 rs_ms,u.busy_ns/1e6 main_stream_busy_ms,(r.dur-u.busy_ns)/1e6 main_stream_idle_ms,(u.last_end-3762433098211544)/1e6 last_main_end_ms,(r.ts+r.dur-u.last_end)/1e6 final_gap_to_rs_end_ms FROM r JOIN u USING(id);
